export interface OutboxRow {
  id: string;
  tenantId: string;
  jobId: string;
  sequence: number;
  topic: string;
  payload: JobEvent;
  publishedAt: Date | null;
  createdAt: Date;
}

export class OutboxRepository {
  async append(client: PoolClient, event: JobEvent): Promise<void> {
    await client.query(
      `INSERT INTO outbox (id, tenant_id, job_id, sequence, topic, payload, created_at)
       VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7)
       ON CONFLICT (tenant_id, job_id, sequence) DO NOTHING`,
      [event.eventId, event.tenantId, event.jobId, event.sequence, "job-events",
       JSON.stringify(event), event.occurredAt],
    );
  }

  async pending(client: PoolClient, limit: number): Promise<OutboxRow[]> {
    const result = await client.query<OutboxRow>(
      `SELECT id, tenant_id AS "tenantId", job_id AS "jobId", sequence, topic,
              payload, published_at AS "publishedAt", created_at AS "createdAt"
       FROM outbox WHERE published_at IS NULL ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT $1`,
      [limit],
    );
    return result.rows;
  }

  async markPublished(client: PoolClient, id: string): Promise<void> {
    await client.query(`UPDATE outbox SET published_at = now() WHERE id = $1`, [id]);
