## `apps/api/src/application/job-service.ts`

```ts
import { randomUUID } from "node:crypto";
import type { Pool } from "pg";
import { ConflictError, NotFoundError } from "../../../packages/shared/src/errors.js";
import { hashRequest, normalizeIdempotencyKey, type IdempotencyRecord } from "../../../packages/shared/src/idempotency.js";
import type { Job, JobState } from "../domain/job.js";
import { assertTransition } from "../domain/job.js";
import { JobRepository } from "../infra/postgres/job-repository.js";
import { OutboxRepository } from "../infra/postgres/outbox-repository.js";
import { JobQueue } from "../infra/redis/job-queue.js";
import type { JobEvent } from "../../../packages/events/src/job-events.js";

export interface CreateJobRequest {
  inputUri: string;
  renderer: "pdf" | "png" | "svg";
}

export interface ServiceResult<T> {
  statusCode: number;
  body: T;
}

export class JobService {
  constructor(
    private readonly pool: Pool,
    private readonly jobs: JobRepository,
    private readonly outbox: OutboxRepository,
    private readonly queue: JobQueue,
  ) {}

  async create(
    tenantId: string,
    request: CreateJobRequest,
    rawKey: string | undefined,
  ): Promise<ServiceResult<Job>> {
    const key = normalizeIdempotencyKey(rawKey);
    if (rawKey && !key) throw new ConflictError("invalid idempotency key", "invalid_idempotency_key");
    const requestHash = hashRequest(request);
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      if (key) {
        const existing = await client.query<IdempotencyRecord>(
          `SELECT tenant_id AS "tenantId", key, request_hash AS "requestHash",
                  status_code AS "statusCode", response_body AS "responseBody", created_at AS "createdAt"
           FROM idempotency_keys WHERE tenant_id = $1 AND key = $2`,
          [tenantId, key],
        );
        const record = existing.rows[0];
        if (record) {
          if (record.requestHash !== requestHash) {
            throw new ConflictError("idempotency key was used with a different request", "idempotency_conflict");
          }
          await client.query("COMMIT");
          return { statusCode: record.statusCode, body: record.responseBody as Job };
        }
      }

      const now = new Date();
      const job: Job = {
        id: randomUUID(), tenantId, state: "queued", inputUri: request.inputUri,
        renderer: request.renderer, outputUri: null, failureCode: null, failureMessage: null,
        version: 0, nextEventSequence: 2, leaseId: null, leaseExpiresAt: null,
        createdAt: now, updatedAt: now,
      };
      await this.jobs.insert(client, job);
      const event: JobEvent = {
        eventId: randomUUID(), tenantId, jobId: job.id, sequence: 1,
        occurredAt: now.toISOString(), type: "job.queued", state: "queued",
        payload: { inputUri: job.inputUri, renderer: job.renderer },
      };
      await this.outbox.append(client, event);
      if (key) {
        await client.query(
          `INSERT INTO idempotency_keys (tenant_id, key, request_hash, status_code, response_body)
           VALUES ($1, $2, $3, $4, $5::jsonb)`,
          [tenantId, key, requestHash, 202, JSON.stringify(job)],
        );
      }
      await client.query("COMMIT");
      await this.queue.enqueue({ jobId: job.id, tenantId, enqueuedAt: now.getTime() });
      return { statusCode: 202, body: job };
    } catch (error) {
      await client.query("ROLLBACK");
      throw error;
    } finally {
      client.release();
    }
  }

  async cancel(tenantId: string, jobId: string, reason: string): Promise<Job> {
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      const job = await this.jobs.lock(client, tenantId, jobId);
      if (!job) throw new NotFoundError("job");
      assertTransition(job.state, "cancelled");
      const next: Job = {
        ...job, state: "cancelled", version: job.version + 1,
        nextEventSequence: job.nextEventSequence + 1, leaseId: null, leaseExpiresAt: null,
        updatedAt: new Date(),
      };
      await this.jobs.updateLocked(client, next);
      await this.outbox.append(client, {
        eventId: randomUUID(), tenantId, jobId, sequence: next.version,
        occurredAt: next.updatedAt.toISOString(), type: "job.cancelled", state: "cancelled",
        payload: { reason },
      });
      await client.query("COMMIT");
      return next;
    } catch (error) {
      await client.query("ROLLBACK");
      throw error;
    } finally {
      client.release();
    }
  }
}
```

