import type { FastifyInstance } from "fastify";
import { eventStreamId, JobEvent } from "../../../packages/events/src/job-events.js";

function parseLastEventId(value: string | undefined): number {
  if (!value) return 0;
  const sequence = Number(value.split(":").at(-1));
  return Number.isSafeInteger(sequence) && sequence >= 0 ? sequence : 0;
}

export async function registerEventRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: { id: string } }>("/v1/jobs/:id/events", async (request, reply) => {
    const tenantId = request.user.tenantId;
    const jobId = request.params.id;
    const after = parseLastEventId(request.headers["last-event-id"]);
    reply.raw.setHeader("Content-Type", "text/event-stream");
    reply.raw.setHeader("Cache-Control", "no-cache");
    reply.raw.setHeader("Connection", "keep-alive");

    const replay = await app.eventStore.listAfter(tenantId, jobId, after);
    for (const row of replay) {
      const event = JobEvent.parse(row.payload);
      reply.raw.write(`id: ${eventStreamId(jobId, event.sequence)}\n`);
