import type Redis from "ioredis";
import { newLease, type Lease, type LeaseStore } from "../../../../packages/queue/src/lease.js";

const acquireScript = `
local key = KEYS[1]
if redis.call('exists', key) == 1 then return 0 end
redis.call('hset', key, 'jobId', ARGV[1], 'workerId', ARGV[2], 'leaseId', ARGV[3])
redis.call('pexpire', key, ARGV[4])
return 1
`;

const renewScript = `
local key = KEYS[1]
if redis.call('hget', key, 'leaseId') ~= ARGV[1] then return 0 end
redis.call('pexpire', key, ARGV[2])
return 1
`;

const releaseScript = `
local key = KEYS[1]
if redis.call('hget', key, 'leaseId') == ARGV[1] then
  return redis.call('del', key)
end
return 0
`;

export class RedisLeaseStore implements LeaseStore {
  constructor(private readonly redis: Redis, private readonly prefix = "lantern:lease:") {}

  async acquire(jobId: string, workerId: string, ttlMs: number): Promise<Lease | null> {
    const lease = newLease(jobId, workerId, ttlMs);
    const ok = await this.redis.eval(acquireScript, 1, this.key(jobId), lease.jobId,
      lease.workerId, lease.leaseId, ttlMs);
    return Number(ok) === 1 ? lease : null;
  }

  async renew(lease: Lease, ttlMs: number): Promise<boolean> {
    const ok = await this.redis.eval(renewScript, 1, this.key(lease.jobId), lease.leaseId, ttlMs);
    if (Number(ok) !== 1) return false;
    lease.expiresAtMs = Date.now() + ttlMs;
    return true;
  }

  async release(lease: Lease): Promise<void> {
    await this.redis.eval(releaseScript, 1, this.key(lease.jobId), lease.leaseId);
  }

  async assertOwned(lease: Lease): Promise<void> {
    const owner = await this.redis.hget(this.key(lease.jobId), "leaseId");
    if (owner !== lease.leaseId) throw new Error("lease lost");
  }

  private key(jobId: string): string { return `${this.prefix}${jobId}`; }
}
