import { applyEvent, type Job } from "../../apps/api/src/domain/job.js";
import { JobEvent, type JobEvent as Event } from "./job-events.js";

export interface ProjectionStore {
  get(tenantId: string, jobId: string): Promise<Job | null>;
  save(job: Job): Promise<void>;
}

export class JobProjector {
  constructor(private readonly store: ProjectionStore) {}

  async consume(raw: unknown): Promise<void> {
    const event = JobEvent.parse(raw);
    const current = await this.store.get(event.tenantId, event.jobId);
    if (!current) {
      if (event.type !== "job.queued") return;
      await this.store.save(jobFromQueued(event));
      return;
    }
    if (event.sequence <= current.version) return;
    await this.store.save(applyEvent(current, event));
  }
}

function jobFromQueued(event: Extract<Event, { type: "job.queued" }>): Job {
  const now = new Date(event.occurredAt);
  return {
    id: event.jobId, tenantId: event.tenantId, state: "queued",
    inputUri: event.payload.inputUri, renderer: event.payload.renderer,
    outputUri: null, failureCode: null, failureMessage: null,
    version: event.sequence, nextEventSequence: event.sequence + 1,
    leaseId: null, leaseExpiresAt: null, createdAt: now, updatedAt: now,
  };
}
