import type { JobEvent } from "./job-events.js";

type Filter = { tenantId: string; jobId: string };
type Listener = { filter: Filter; callback: (event: JobEvent) => void };

export class InMemoryEventBus {
  private readonly listeners = new Set<Listener>();

  subscribe(filter: Filter, callback: (event: JobEvent) => void): () => void {
    const listener = { filter, callback };
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  publish(event: JobEvent): void {
    for (const listener of this.listeners) {
      if (listener.filter.tenantId === event.tenantId && listener.filter.jobId === event.jobId) {
        queueMicrotask(() => listener.callback(event));
      }
    }
  }
}
