import { randomUUID } from "node:crypto";
import type { Pool, PoolClient } from "pg";
import { assertTransition, type Job } from "../domain/job.js";
import { JobRepository } from "../infra/postgres/job-repository.js";
import { OutboxRepository } from "../infra/postgres/outbox-repository.js";
import { EventStore } from "../../../packages/events/src/event-store.js";
import type { JobEvent, JobState } from "../../../packages/events/src/job-events.js";

export class JobTransitionService {
  constructor(
    private readonly pool: Pool,
    private readonly jobs: JobRepository,
    private readonly events: EventStore,
    private readonly outbox: OutboxRepository,
  ) {}

  async transition(
    tenantId: string,
    jobId: string,
    nextState: JobState,
    payload: Record<string, unknown>,
    predicate?: (job: Job) => boolean,
  ): Promise<Job> {
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      const job = await this.jobs.lock(client, tenantId, jobId);
      if (!job) throw new Error("job not found");
      if (predicate && !predicate(job)) throw new Error("transition predicate failed");
      assertTransition(job.state, nextState);
      const version = job.version + 1;
      const now = new Date();
      const next = { ...job, state: nextState, version, nextEventSequence: version + 1, updatedAt: now };
      await this.jobs.updateLocked(client, next);
      const event = this.buildEvent(job, next, payload);
      await this.events.append(client, event);
      await this.outbox.append(client, event);
      await client.query("COMMIT");
      return next;
    } catch (error) {
      await client.query("ROLLBACK");
      throw error;
    } finally { client.release(); }
  }

  private buildEvent(previous: Job, next: Job, payload: Record<string, unknown>): JobEvent {
    const type = `job.${next.state}` as JobEvent["type"];
    return {
      eventId: randomUUID(), tenantId: next.tenantId, jobId: next.id,
      sequence: next.version, occurredAt: next.updatedAt.toISOString(),
      type, state: next.state, payload,
    } as JobEvent;
  }
}
